MAP
    NAME "SS_MAP_DREN_DRENAJE_MEDIDORES_SEC"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_drenaje_medidores_sector.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_DREN_MEDIDORES_SEC_UBICACION"
        PROJECTION
            'init=epsg:32614'
        END #PROJECION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "gm_drenaje_medidor_sector from l_drenaje_medidores_sector using unique id_drenaje_medidor_sector using srid=32614"
        TYPE POINT
        LABELITEM "nb_drenaje_medidor_sector"
        LABELCACHE on
        CLASS
            NAME "Sectores_medidores"
            STYLE
                SYMBOL "puntos"
                SIZE 8
                COLOR 161 102 50
                OUTLINECOLOR 161 102 50
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 19
                COLOR 161 102 50
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP